sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.poster_holder {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}

@keyframes posterFadeIn {
  from {
    opacity: 0;
    transform: translateY(15px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes shine {
  from { left: -75%; }
  to { left: 125%; }
}

#poster_image {
  display: block;
  margin: 0 auto;
  width: 250px;

  border-radius: 16px;
  border: none;
  outline: none;
  background: transparent;

  position: relative;
  overflow: hidden;
  cursor: pointer;

  animation: posterFadeIn 0.5s ease-out;
  /* ALTERE A COR AQUI */
  box-shadow: 
    0 10px 25px rgba(217, 79, 138, 0.35),
    0 4px 10px rgba(217, 79, 138, 0.25);

  transition: 
    transform 0.3s ease,
    box-shadow 0.3s ease,
    filter 0.3s ease;

  will-change: transform;
}

#poster_image:hover {
  transform: scale(1.08) rotateX(2deg) rotateY(-2deg);

  /* ALTERE A COR AQUI */
  box-shadow: 
    0 25px 50px rgba(217, 79, 138, 0.45),
    0 12px 25px rgba(217, 79, 138, 0.35);

  filter: brightness(1.05) saturate(1.1);
}

#poster_image:active {
  transform: scale(0.97);
}

#poster_image::after {
  content: "";
  position: absolute;
  top: 0;
  left: -75%;
  width: 50%;
  height: 100%;

  /* ALTERE A COR AQUI */
  background: linear-gradient(
    120deg,
    transparent,
    rgba(255, 255, 255, 0.25),
    transparent
  );

  transform: skewX(-25deg);
}

#poster_image:hover::after {
  animation: shine 0.8s ease;
}

/* esconder imagem inválida */
#poster_image[src=""],
#poster_image:not([src]),
#poster_image[src="null"],
#poster_image[src="undefined"] {
  display: none;
}
